  1682  static void sc_free_entry(struct sc_asn1_entry *asn1) {
  1683          int idx = 0;
  1684          struct sc_asn1_entry *entry = asn1;
  1685
  1686          if (!asn1)
  1687                  return;
  1688
  1689          for (idx = 0; asn1[idx].name != NULL; idx++) {
  1690                  entry = &asn1[idx];
  1691                  switch (entry->type) {
  1692                  case SC_ASN1_CHOICE:
  1693                  case SC_ASN1_STRUCT:
  1694                          sc_free_entry((struct sc_asn1_entry *) entry->parm);
  1695                          break;
  1696                  case SC_ASN1_OCTET_STRING:
  1697                  case SC_ASN1_BIT_STRING_NI:
  1698                  case SC_ASN1_BIT_STRING:
  1699                  case SC_ASN1_GENERALIZEDTIME:
  1700                  case SC_ASN1_PRINTABLESTRING:
  1701                  case SC_ASN1_UTF8STRING:
  1702                          if ((entry->flags & SC_ASN1_ALLOC) && (entry->flags & SC_ASN1_PRESENT)) {
  1703                                  u8 **buf = (u8 **)entry->parm;
  1704                                  free(*buf);
  1705                                  *buf = NULL;
  1706                          }
  1707                          break;
  1708                  default:
  1709                          break;
  1710                  }
  1711          }
  1712  }
