  1714  static int asn1_decode(sc_context_t *ctx, struct sc_asn1_entry *asn1,
  1715                         const u8 *in, size_t len, const u8 **newp, size_t *len_left,
  1716                         int choice, int depth)
  1717  {
  1718          int r, idx = 0;
  1719          const u8 *p = in, *obj;
  1720          struct sc_asn1_entry *entry = asn1;
  1721          size_t left = len, objlen;
  1722
  1723          sc_debug(ctx, SC_LOG_DEBUG_ASN1,
  1724                   "%*.*s""called, left=%"SC_FORMAT_LEN_SIZE_T"u, depth %d%s\n",
  1725                   depth, depth, "", left, depth, choice ? ", choice" : "");
  1726
  1727          if (!p)
  1728                  return SC_ERROR_ASN1_OBJECT_NOT_FOUND;
  1729          if (left < 2) {
  1730                  while (asn1->name && (asn1->flags & SC_ASN1_OPTIONAL))
  1731                          asn1++;
  1732                  /* If all elements were optional, there's nothing
  1733                   * to complain about */
  1734                  if (asn1->name == NULL)
  1735                          return 0;
  1736                  sc_debug(ctx, SC_LOG_DEBUG_ASN1, "End of ASN.1 stream, "
  1737                                "non-optional field \"%s\" not found\n",
  1738                                asn1->name);
  1739                  return SC_ERROR_ASN1_OBJECT_NOT_FOUND;
  1740          }
  1741          if (p[0] == 0 || p[0] == 0xFF || len == 0)
  1742                  return SC_ERROR_ASN1_END_OF_CONTENTS;
  1743
  1744          for (idx = 0; asn1[idx].name != NULL; idx++) {
  1745                  entry = &asn1[idx];
  1746
  1747                  sc_debug(ctx, SC_LOG_DEBUG_ASN1, "Looking for '%s', tag 0x%x%s%s\n",
  1748                          entry->name, entry->tag, choice? ", CHOICE" : "",
  1749                          (entry->flags & SC_ASN1_OPTIONAL)? ", OPTIONAL": "");
  1750
  1751                  /* Special case CHOICE has no tag */
  1752                  if (entry->type == SC_ASN1_CHOICE) {
  1753                          r = asn1_decode(ctx,
  1754                                  (struct sc_asn1_entry *) entry->parm,
  1755                                  p, left, &p, &left, 1, depth + 1);
  1756                          if (r >= 0)
  1757                                  r = 0;
  1758                          goto decode_ok;
  1759                  }
  1760
  1761                  obj = sc_asn1_skip_tag(ctx, &p, &left, entry->tag, &objlen);
  1762                  if (obj == NULL) {
  1763                          sc_debug(ctx, SC_LOG_DEBUG_ASN1, "'%s' not present\n", entry->name);
  1764                          if (choice)
  1765                                  continue;
  1766                          if (entry->flags & SC_ASN1_OPTIONAL)
  1767                                  continue;
  1768                          sc_debug(ctx, SC_LOG_DEBUG_ASN1, "mandatory ASN.1 object '%s' not found\n", entry->name);
  1769                          if (left) {
  1770                                  u8 line[128], *linep = line;
  1771                                  size_t i;
  1772
  1773                                  line[0] = 0;
  1774                                  for (i = 0; i < 10 && i < left; i++) {
  1775                                          sprintf((char *) linep, "%02X ", p[i]);
  1776                                          linep += 3;
  1777                                  }
  1778                                  sc_debug(ctx, SC_LOG_DEBUG_ASN1, "next tag: %s\n", line);
  1779                          }
  1780                          sc_free_entry(asn1);
  1781                          SC_FUNC_RETURN(ctx, SC_LOG_DEBUG_ASN1, SC_ERROR_ASN1_OBJECT_NOT_FOUND);
  1782                  }
  1783                  r = asn1_decode_entry(ctx, entry, obj, objlen, depth);
  1784
  1785  decode_ok:
  1786                  if (r)
  1787                          return r;
  1788                  if (choice)
  1789                          break;
  1790          }
  1791          if (choice && asn1[idx].name == NULL) /* No match */
  1792                  SC_FUNC_RETURN(ctx, SC_LOG_DEBUG_ASN1, SC_ERROR_ASN1_OBJECT_NOT_FOUND);
  1793          if (newp != NULL)
  1794                  *newp = p;
  1795          if (len_left != NULL)
  1796                  *len_left = left;
  1797          if (choice)
  1798                  SC_FUNC_RETURN(ctx, SC_LOG_DEBUG_ASN1, idx);
  1799          SC_FUNC_RETURN(ctx, SC_LOG_DEBUG_ASN1, 0);
  1800  }
